def count_decodings(code):
    n = len(code)
    dp = [0] * (n + 1)
    dp[0] = 1
    for i in range(1, n + 1):
        if code[i - 1] != '0':
            dp[i] += dp[i - 1]
        if i >= 2 and (code[i - 2] == '1' or (code[i - 2] == '2' and code[i - 1] <= '6')):
            dp[i] += dp[i - 2]
    return dp[n]
